    // await vault.approleLogin({ role_id: process.env.VAULT_ROLE_ID, secret_id: process.env.VAULT_SECRET_ID });
    // const { data } = await vault.read('secret/data/my-app');
    // return data.data;

    // Option C: Google Secret Manager
    // const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    // const client = new SecretManagerServiceClient();
    // ...

  } else {
    // Development: use dotenv with validation
    require('dotenv').config();
    return {
      databaseUrl: process.env.DATABASE_URL,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      anthropicApiKey: process.env.ANTHROPIC_API_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      logfireToken: process.env.LOGFIRE_TOKEN,
    };
  }
};

module.exports = { loadSecrets };
```

### 4. **Validate Required Secrets at Startup**

```javascript
// config/validateEnv.js
const requiredSecrets = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID', 
  'AWS_SECRET_ACCESS_KEY',
  'STRIPE_SECRET_KEY',
];

const validateSecrets = (secrets) => {
  const missing = requiredSecrets.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  // Validate format
  if (secrets.DATABASE_URL && !secrets.DATABASE_URL.startsWith('postgres://')) {
    throw new Error('DATABASE_URL must be a valid PostgreSQL connection string');
  }

  if (secrets.AWS_ACCESS_KEY_ID && !/^AKIA[A-Z0-9]{16}$/.test(secrets.AWS_ACCESS_KEY_ID)) {
    console.warn('Warning: AWS_ACCESS_KEY_ID format looks unusual');
  }

  return true;
};

module.exports = { validateSecrets };
```

### 5. **Updated app.js with Secure Secret Loading**

```javascript
// app.js - with secure secrets management
const express = require('express');
const helmet = require('helmet');
const { loadSecrets } = require('./config/secrets');
const { validateSecrets } = require('./config/validateEnv');

const app = express();

const startServer = async () => {
  try {
    // Load and validate secrets
    const secrets = await loadSecrets();
    validateSecrets(secrets);

    // Make secrets available (but don't expose globally)
    app.locals.secrets = secrets;

    app.use(helmet());

    app.get('/health', (req, res) => {
      res.json({ status: 'ok' });
    });

    // Example: using secrets securely
    app.get('/users', async (req, res) => {
      // Access secrets through app.locals, not process.env
      // const db = await connectDb(req.app.locals.secrets.databaseUrl);
      res.json([{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }]);
    });

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });

  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1);
  }
};

startServer();

module.exports = app;
```

### 6. **Additional Security Measures**

```javascript
// Prevent secrets from leaking in logs
const sanitizeForLogging = (obj) => {
  const sensitiveKeys = /password|secret|key|token|auth/i;
  return JSON.stringify(obj, (key, value) => {
    if (sensitiveKeys.test(key)) {
      return '[REDACTED]';
    }
    return value;
  });
};

// Don't log the full error in production
app.use((err, req, res, next) => {
  console.error('Error:', sanitizeForLogging({
    message: err.message,
    url: req.url,
    // Never log: err.stack in production (may contain secrets)
  }));
  res.status(500).json({ error: 'Internal server error' });
});
```

