### 📝 Recommended Secure Secrets Architecture

```javascript
// config/index.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class ConfigManager {
  constructor() {
    this.secrets = null;
    this.loaded = false;
  }

  async load() {
    if (this.loaded) return this.secrets;

    if (process.env.NODE_ENV === 'production') {
      this.secrets = await this.loadFromSecretsManager();
    } else {
      this.secrets = this.loadFromEnv();
    }

    this.loaded = true;
    this.validateRequiredSecrets();
    return this.secrets;
  }

  async loadFromSecretsManager() {
    const client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });

    const command = new GetSecretValueCommand({ 
      SecretId: process.env.SECRETS_ID || 'myapp/secrets'
    });

    const response = await client.send(command);
    return JSON.parse(response.SecretString);
  }

  loadFromEnv() {
    // Only load dotenv in non-production
    require('dotenv').config();

    return {
      databaseUrl: process.env.DATABASE_URL,
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      },
      anthropicApiKey: process.env.ANTHROPIC_API_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      logfireToken: process.env.LOGFIRE_TOKEN,
    };
  }

  validateRequiredSecrets() {
    const required = ['databaseUrl'];
    for (const key of required) {
      if (!this.secrets[key]) {
        throw new Error(`Missing required secret: ${key}`);
      }
    }
  }

  // Prevent accidental logging of secrets
  get(key) {
    return this.secrets[key];
  }
}

module.exports = new ConfigManager();
```

