## ✅ Recommendations

### 1. Use a Secrets Manager

For production, use a dedicated secrets manager:

```javascript
// config/secrets.js - AWS Secrets Manager example
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: 'us-east-1' });

async function getSecrets(secretName) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);
    return JSON.parse(response.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secrets:', error.message);
    throw error;
  }
}

// Usage
async function initializeApp() {
  const secrets = await getSecrets('myapp/production');

  return {
    databaseUrl: secrets.DATABASE_URL,
    stripeKey: secrets.STRIPE_SECRET_KEY,
    // ... other secrets
  };
}

module.exports = { getSecrets, initializeApp };
```

### 2. Alternative: HashiCorp Vault

```javascript
// config/vault.js
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN, // Use AppRole in production
});

async function getSecrets(path) {
  try {
    const result = await vault.read(path);
    return result.data.data;
  } catch (error) {
    console.error('Vault error:', error.message);
    throw error;
  }
}

module.exports = { getSecrets };
```

### 3. Add .env to .gitignore

```bash
# .gitignore
.env
.env.*
!.env.example
```

