### 5. Implement Secure Config Loading

```javascript
// config/index.js
const path = require('path');

function loadConfig() {
  const env = process.env.NODE_ENV || 'development';

  // Only load .env files in development
  if (env === 'development') {
    require('dotenv').config({
      path: path.resolve(process.cwd(), '.env.local')
    });
  }

  // Validate required environment variables
  const required = [
    'DATABASE_URL',
    'JWT_SECRET',
  ];

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  // Return sanitized config object
  return Object.freeze({
    database: {
      url: process.env.DATABASE_URL,
      poolSize: parseInt(process.env.DB_POOL_SIZE, 10) || 10,
    },
    jwt: {
      secret: process.env.JWT_SECRET,
      expiresIn: process.env.JWT_EXPIRES_IN || '1h',
    },
    stripe: {
      secretKey: process.env.STRIPE_SECRET_KEY,
    },
    // Don't include AWS keys here - use IAM roles instead
  });
}

module.exports = loadConfig();
```

### 6. Use IAM Roles Instead of Access Keys (AWS)

```javascript
// For AWS services, use IAM roles instead of access keys
// The SDK will automatically use the instance/container role

const { S3Client } = require('@aws-sdk/client-s3');

// No credentials needed - uses IAM role automatically
const s3Client = new S3Client({ region: 'us-east-1' });
```

